                for c_idx in B_cols:
                    n = r*W + cols[c_idx] + 1
                    if isprime(n):
                        primes_used.add(n)
            # Off-diagonal upper block entries: row 0 -> A,B; A_rows -> B_cols
            for r in A_rows:
